import json
import secrets
import sys
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer


def handler(inference_key: str, observer_key: str):
    lock = threading.Lock()
    counts = {"received": 0, "authorized": 0, "models": []}

    class Handler(BaseHTTPRequestHandler):
        def log_message(self, *_: object) -> None:
            pass

        def authorized(self, key: str) -> bool:
            supplied = self.headers.get("Authorization", "")
            return secrets.compare_digest(supplied, "Bearer " + key)

        def reply(self, code: int, body: dict) -> None:
            encoded = json.dumps(body).encode()
            self.send_response(code)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(encoded)))
            self.end_headers()
            self.wfile.write(encoded)

        def do_GET(self) -> None:
            if self.path != "/_fixture/counts" or not self.authorized(observer_key):
                self.reply(401, {"error": "unauthorized"})
                return
            with lock:
                self.reply(200, counts)

        def do_POST(self) -> None:
            with lock:
                counts["received"] += 1
            if self.path != "/v1/chat/completions" or not self.authorized(inference_key):
                self.reply(401, {"error": "unauthorized"})
                return
            try:
                length = int(self.headers.get("Content-Length", "0"))
                if not 0 < length <= 65536:
                    raise ValueError()
                request = json.loads(self.rfile.read(length))
                model = request.get("model")
                if model not in ("fixture-personal", "fixture-family") or request.get("stream"):
                    raise ValueError()
            except (ValueError, TypeError, AttributeError):
                self.reply(400, {"error": "unsupported_fixture_request"})
                return
            with lock:
                counts["authorized"] += 1
                counts["models"].append(model)
            self.reply(200, {
                "id": "fixture-completion", "object": "chat.completion", "created": 1,
                "model": model,
                "choices": [{"index": 0, "message": {"role": "assistant", "content": "fixture-ok"},
                             "finish_reason": "stop"}],
                "usage": {"prompt_tokens": 1, "completion_tokens": 1, "total_tokens": 2},
            })

    return Handler


def main() -> None:
    credentials = json.loads(sys.stdin.readline())
    server = ThreadingHTTPServer(
        ("0.0.0.0", 8000), handler(credentials["inference"], credentials["observer"])
    )
    server.serve_forever()


if __name__ == "__main__":
    main()

